    """Evaluate an expression in Reverse Polish Notation.
    Supports operators +, -, *, / with integer division truncating toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Python's int division truncates toward -inf, need truncate toward zero
                if a * b < 0:
                    res = - (abs(a) // abs(b))
                else:
                    res = a // b
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

