def solve(tokens):
    """Evaluate RPN expression with integer division truncating toward zero.
    Uses only integer arithmetic to avoid floating point issues.
    """
    stack = []
    for t in tokens:
        if t not in {"+", "-", "*", "/"}:
            stack.append(int(t))
        else:
            b = stack.pop()
            a = stack.pop()
            if t == "+":
                stack.append(a + b)
            elif t == "-":
                stack.append(a - b)
            elif t == "*":
                stack.append(a * b)
            else:  # division truncates toward zero
                # Perform integer division without using float
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
    return stack[0] if stack else 0

