def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Simple O(n^2) DP works for typical constraints and avoids subtle
    issues with the patience‑sorting method on edge cases.
    """
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n  # dp[i] = length of LIS ending at i
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

