def solve(tokens):
    def trunc_div(a, b):
        if b == 0:
            raise ZeroDivisionError('division by zero')
        sign = -1 if (a < 0) ^ (b < 0) else 1
        return sign * (abs(a) // abs(b))
    stack = []
    for tok in tokens:
        if tok in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:
                stack.append(trunc_div(a, b))
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

